WITH filtered AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, ROUND(discount * 0.9, 2) AS discount_adjusted, CASE WHEN channel IN ('store', 'web') THEN 'Tier 1' ELSE 'Other' END AS channel_group, COALESCE(channel, 'NONE') AS channel_filled FROM orders WHERE channel IS NOT NULL) SELECT src.*, d.sqft FROM filtered src LEFT JOIN stores d ON src.store_id = d.id
